mapper.select:
SELECT 
FROM reservation

    AND status = #{status}
    AND artist_id = #{artistId}
    AND created_at >= #{startDate}
    AND created_at <= #{endDate}


ORDER BY created_at DESC

mapper.update:
UPDATE reservation
SET status = #{status}
WHERE id = #{id}

UPDATE reservation
SET status = 'CONFIRMED',
confirm_date = #{confirmedDate}
WHERE id = #{id}

mapper.select:
SELECT EXISTS (
    SELECT 1 FROM reservation WHERE reservation_no = #{reservationNo}
)
